{
  "technical_and_design_decisions": [
    "Target environment is built on the Spring XD framework architecture, leveraging Spring Integration, Spring Boot, and Spring Security on Java 17+.",
    "U1 implementation uses RabbitAdmin and RabbitManagementTemplate to inspect consumer counts and safely remove queues, bindings, and fanout exchanges upon stream destroy with --clean.",
    "U2 utilizes Spring XD's error channel mechanism per stream/module to capture exceptions and route error messages to a dedicated stream error bus.",
    "U3 is executed as a technical spike delivering a design proposal, prototype implementation, and developer configuration guidelines for Spring Security integration across REST, Shell, and Admin UI.",
    "U5 implements an HTTP source module using embedded Tomcat and Spring MVC to enable full HTTP header mapping, content-type negotiation, and custom REST controller support.",
    "U6 introduces a client polling strategy in the Shell and Admin UI along with a server-side event publisher to broadcast stream/job lifecycle status changes.",
    "U7 leverages Spring Integration SFTP adapters (SftpInboundFileSynchronizer) and includes an embedded SFTP test server setup for automated integration testing.",
    "U8 utilizes the Elasticsearch Java Client for high-throughput batch and single-document indexing in a native ElasticSearch sink module."
  ],
  "assumptions": [
    "Development work will be performed by a senior developer familiar with Spring XD, Spring Integration, and Spring Boot internal abstractions.",
    "Docker / Testcontainers infrastructure is available locally for integration tests against RabbitMQ, SFTP, and ElasticSearch.",
    "U3 is scoped as a spike (research, design, and prototype) as specified, with production rollout across all REST endpoints slated for a subsequent phase based on the spike outcomes.",
    "All new modules (HTTP MVC, SFTP, ElasticSearch) will adhere to Spring XD module layout standards, including metadata declaration and documentation."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Stream Destroy Resource Cleanup (U1)",
      "activity_description": "Implement '--clean' option in CLI/REST API for stream destroy command; add RabbitAdmin / RabbitManagementTemplate logic to check active consumers, queues, bindings, and fanout exchanges prior to deletion.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Module Exception Notification & Error Channel (U2)",
      "activity_description": "Expose module-level error channels in Spring XD stream runner to catch exceptions and publish failure events to dedicated stream error channels.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Security Configuration Spike (U3)",
      "activity_description": "Research Spring Security and Spring Boot OOTB features; design security layer approach for REST endpoints, DSL Shell authentication, and Admin UI; create prototype implementation and document design considerations.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Property Placeholder Documentation (U4)",
      "activity_description": "Audit and document available runtime expression evaluation keys such as ${xd.stream.name}, ${xd.job.name}, and ${xd.container.*} across module configurations.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "OOTB MVC-Aware HTTP Source Module (U5)",
      "activity_description": "Develop HTTP source module with embedded Tomcat and Spring MVC, enabling rich content-type support, full header mapping, and custom request processing; write unit and integration tests.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Job & Stream Status Polling and Server Event Propagation (U6)",
      "activity_description": "Implement client-side status polling in Shell/Admin UI and build server-side event propagation mechanism between containers and Admin server for lifecycle state changes.",
      "most_likely_effort": 36
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "SFTP Source Module & Test Infrastructure (U7)",
      "activity_description": "Implement SFTP source module using Spring Integration SFTP adapters; set up embedded SFTP test server infrastructure for integration testing; create documentation.",
      "most_likely_effort": 26
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Native ElasticSearch Sink Module (U8)",
      "activity_description": "Design and build ElasticSearch sink module supporting document indexing, bulk operations, and cluster configuration; add integration tests using ElasticSearch test container.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "End-to-End Integration Testing & Documentation",
      "activity_description": "Perform overall integration testing across new modules and features, update reference documentation, and verify CLI and Admin UI compatibility.",
      "most_likely_effort": 20
    }
  ],
  "reported_total": {
    "most_likely_effort": 214
  }
}
